const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define the date of interest.
    const date = '2018-02-14';

    // Geometries for the Great Lakes. Using a public FeatureCollection for accuracy.
    const lakes = ee.FeatureCollection('EPA/Ecoregions/2013/L3')
        .filter(ee.Filter.inList('us_l3name', ['Erie Drift Plain', 'Huron/Erie Lake Plain', 'Eastern Corn Belt Plains']));

    const lakeErie = ee.FeatureCollection("HYDROSHEDS/WWF/GLAKES")
        .filter(ee.Filter.eq('LAKE_NAME', 'Erie')).geometry();
    const otherLakes = ee.FeatureCollection("HYDROSHEDS/WWF/GLAKES")
        .filter(ee.Filter.inList('LAKE_NAME', ['Superior', 'Huron', 'Michigan', 'Ontario'])).geometry();

    // 2. Data Acquisition & Check
    // MODIS Daily Snow Cover product, which includes lake ice.
    const collection = ee.ImageCollection('MODIS/061/MOD10A1')
        .filterDate(date, ee.Date(date).advance(1, 'day'));

    const image = collection.first();

    // C1: Check if an image exists for the date.
    const imageCount = collection.size().getInfo();
    if (imageCount === 0) {
        console.log(`No MODIS images found for ${date}.`);
        console.log('A'); // Fallback: MODIS has global daily coverage, so an empty collection is highly unlikely unless the date is invalid. Let's assume 'A' if this happens.
        return;
    }

    // 3. Processing
    // The 'NDSI_Snow_Cover' band contains ice percentage. Valid values are 0-100.
    const iceBand = image.select('NDSI_Snow_Cover');

    // Create a mask for valid pixels (ice or water), excluding clouds and other flags.
    const validPixelMask = iceBand.lte(100);
    const maskedIce = iceBand.updateMask(validPixelMask);

    // Set a high scale due to the large area of the Great Lakes to avoid timeouts.
    const scale = 3000;

    // 4. Calculation
    // Calculate the mean ice percentage for Lake Erie.
    const erieStats = maskedIce.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: lakeErie,
        scale: scale,
        maxPixels: 1e9
    });

    // Calculate the mean ice percentage for the other Great Lakes combined.
    const otherStats = maskedIce.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: otherLakes,
        scale: scale,
        maxPixels: 1e9
    });

    const erieIce = erieStats.get('NDSI_Snow_Cover_mean').getInfo();
    const eriePixels = erieStats.get('NDSI_Snow_Cover_count').getInfo();

    const otherIce = otherStats.get('NDSI_Snow_Cover_mean').getInfo();
    const otherPixels = otherStats.get('NDSI_Snow_Cover_count').getInfo();

    // 5. Validation & Final Answer
    // C2: Check for valid pixels.
    if (eriePixels === 0 || otherPixels === 0) {
        console.log(`Lake Erie Valid Pixels: ${eriePixels}`);
        console.log(`Other Lakes Valid Pixels: ${otherPixels}`);
        console.log('No valid pixels found after cloud masking.');
        console.log('C2');
        return;
    }

    // C3: Check for calculation failure.
    if (erieIce === null || otherIce === null) {
        console.log(`Lake Erie Ice %: ${erieIce}`);
        console.log(`Other Lakes Ice %: ${otherIce}`);
        console.log('Calculation resulted in null.');
        console.log('C3');
        return;
    }

    console.log(`Date: ${date}`);
    console.log(`Lake Erie Avg Ice Coverage: ${erieIce.toFixed(2)}%`);
    console.log(`Lake Erie Valid Pixels: ${eriePixels}`);
    console.log(`Other Great Lakes Avg Ice Coverage: ${otherIce.toFixed(2)}%`);
    console.log(`Other Great Lakes Valid Pixels: ${otherPixels}`);

    if (erieIce > otherIce) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
